function Person({label,value,users,change}:{label:string;value:number;users:HubRow[];change:(value:number)=>void}){return <label>{label}<select className="textInput" value={value} onChange={event=>change(Number(event.target.value))}>{users.map(user=><option value={user.id} disabled={user.active===false} key={user.id}>{user.username}{user.active===false?' (disabled)':''}</option>)}</select></label>;}
