  const [selected,setSelected]=useState<File[]>([]),[progress,setProgress]=useState<HubRow|null>(null),[busy,setBusy]=useState(false),[error,setError]=useState('');const input=useRef<HTMLInputElement>(null),directory=useRef<HTMLInputElement>(null),abort=useRef<AbortController|null>(null);
