  const upload=async(files=selected)=>{if(!files.length||busy)return;setSelected(files);setBusy(true);onBusy?.(true);setError('');let completed=0;const controller=new AbortController();abort.current=controller;try{await uploadFiles(project,files,setProgress,record=>{completed++;onFiles([record]);},controller.signal);setSelected([]);}catch(error){setSelected(files.slice(completed));setError((error as Error).name==='AbortError'?'Upload paused. Keep or reselect the same files to resume.':(error as Error).message);}finally{setBusy(false);onBusy?.(completed<files.length);if(completed===files.length)onComplete?.();}};
